    items: [{"front": "Simile", "back": "Comparison using \"like\" / \"as\" — Brave as a lion", "sub": ""}, {"front": "Metaphor", "back": "Direct comparison, no like/as — He is the Einstein of my class", "sub": ""}, {"front": "Personification", "back": "A non-human thing acts human — Death lays his icy hand on kings", "sub": ""}, {"front": "Oxymoron", "back": "Two contradictory words forced together — Faith unfaithful kept him falsely true", "sub": ""}, {"front": "Hyperbole", "back": "Deliberate, obvious exaggeration — I could eat a horse", "sub": ""}, {"front": "Alliteration", "back": "Same consonant sound starts nearby words — She sells seashells", "sub": ""}, {"front": "Irony", "back": "The opposite of what is literally said or expected — Calling a very unlucky day \"a lucky one\"", "sub": ""}, {"front": "Apostrophe", "back": "Addressing something absent, abstract or non-human directly — O Death, where is thy sting?", "sub": ""}, {"front": "Metonymy", "back": "Substituting a closely-associated thing for the thing itself — \"The crown\" for the monarchy", "sub": ""}, {"front": "Onomatopoeia", "back": "A word that imitates the sound it describes — Buzz, hiss, clang", "sub": ""}],
